layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1) }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 12px; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1) }
[data-ryt="footer"] { color: var(--ryt-text); background-color: var(--ryt-header-bg); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="button"] { color: rgb(221, 238, 255); background-color: rgb(58, 70, 104); border-radius: 28px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(221, 238, 255); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 24px; padding-bottom: 0px; padding-left: 16px; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1); position: relative }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1) }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: Raleway, system-ui, sans-serif; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1) }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.684; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1) }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 15.102px; font-weight: 500; font-style: normal; line-height: 1.784; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1) }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); background-color: var(--ryt-surface); border-radius: 12px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1); position: relative }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: Raleway, system-ui, sans-serif; font-size: 22.6274px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.684; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 28.5088px; font-weight: 400; font-style: normal; line-height: 0.945; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.4s cubic-bezier(0.2, 0, 0, 1) }
[data-ryt="rec-card"] [data-ryt="title"] a::before { content: ""; display: block; position: absolute; width: 100%; height: 273.062px; color: var(--ryt-text); background-color: var(--ryt-surface); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.3) 0px 1px 2px 0px, rgba(0, 0, 0, 0.15) 0px 1px 3px 1px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.684; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 0px; left: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a::after { content: ""; display: block; position: absolute; width: 100%; height: 273.062px; color: var(--ryt-text); background-image: radial-gradient(circle, var(--ryt-text) 1%, rgba(0, 0, 0, 0) 1%); background-size: auto; background-position: 50% 50%; background-repeat: repeat; border-radius: 12px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.684; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 0px; left: 0px }
[data-ryt="button"]::before { content: ""; display: block; position: absolute; width: 100%; height: 40px; color: rgb(221, 238, 255); background-color: rgb(58, 70, 104); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 28px; font-family: var(--ryt-font-heading); font-size: 15.102px; font-weight: 500; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(221, 238, 255); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(221, 238, 255); top: 0px; left: 0px }
[data-ryt="button"]::after { content: ""; display: block; position: absolute; width: 100%; height: 40px; color: rgb(221, 238, 255); background-image: radial-gradient(circle, rgb(221, 238, 255) 1%, rgba(0, 0, 0, 0) 1%); background-size: auto; background-position: 50% 50%; background-repeat: repeat; border-radius: 28px; font-family: var(--ryt-font-heading); font-size: 15.102px; font-weight: 500; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(221, 238, 255); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(221, 238, 255); top: 0px; left: 0px }
